import React, { useState, useEffect } from "react";
import {
  AlertTriangle, Plus, Search, FileText, Eye, Edit2, Hash,
  X, MapPin, Clock, User, Truck, CheckCircle, AlertOctagon
} from "lucide-react";
import {
  formatFechaHora, getEstadoColor, getPrioridadColor
} from "../utils/helpers";
import Toast from "../components/ui/Toast";
import DynamicForm from "../components/DynamicForm/DynamicForm";
import NovedadesTable from "../components/DynamicTable/DynamicTable";
import { getCookie } from "../utils/csrf";

const API_BASE = "http://localhost:8000/api";

// Choices reales del modelo Novedades (mantener sincronizado con
// apps/novedades/models.py -> ESTADOS_NOVEDADES_CHOICES / NIVEL_PRIORIDAD).
// Idealmente esto se trae del endpoint /api/formulario/novedades/ para no
// tener que actualizar dos lugares cuando cambien los choices en Django.
const ESTADOS_NOVEDAD = [
  { value: "Todos", label: "Todos" },
  { value: "Pendiente_por_responder", label: "Pendiente por responder" },
  { value: "Completado", label: "Completado" },
  { value: "Informacion_incompleta", label: "Información incompleta" },
];

const PRIORIDADES_NOVEDAD = [
  { value: "Todos", label: "Todos" },
  { value: "Prioridad_Alta", label: "Alta" },
  { value: "Prioridad Media", label: "Media" },
  { value: "Prioridad_Media", label: "Media" },
  { value: "Prioridad_Baja", label: "Baja" },
];

function DetailField({ icon: Icon, label, value }) {
  return (
    <div
      style={{
        display: "flex",
        gap: 10,
        padding: "10px 12px",
        background: "var(--bg-surface)",
        borderRadius: "var(--radius-sm)",
        border: "1px solid var(--border)",
      }}
    >
      <Icon size={14} color="var(--accent-primary)" style={{ marginTop: 2, flexShrink: 0 }} />
      <div style={{ minWidth: 0 }}>
        <div
          style={{
            fontSize: 10,
            color: "var(--text-muted)",
            marginBottom: 1,
            textTransform: "uppercase",
            letterSpacing: "0.04em",
          }}
        >
          {label}
        </div>
        <div
          style={{ fontSize: 13, color: "var(--text-primary)", fontWeight: 500 }}
          title={typeof value === "string" ? value : undefined}
        >
          {value || "—"}
        </div>
      </div>
    </div>
  );
}

function DetailSection({ title, fields }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <div
        style={{
          fontSize: 11,
          fontWeight: 600,
          color: "var(--text-muted)",
          textTransform: "uppercase",
          letterSpacing: "0.05em",
          marginBottom: 8,
        }}
      >
        {title}
      </div>
      <div className="grid-2" style={{ gap: 12 }}>
        {fields.map((field) => (
          <DetailField key={field.id} {...field} />
        ))}
      </div>
    </div>
  );
}

function ModalNovedad({ novedad, onClose, onSave, onGenerarInforme }) {
  console.log(novedad);
  const isEdit = !!novedad?.id;

  return (
    <div className="modal-overlay">
      <div className="modal modal-lg">
        <div className="modal-header">
          <div className="modal-title">
            <AlertTriangle size={18} />
            {isEdit ? "Editar novedad" : "Registrar novedad"}
          </div>
          <button className="btn-icon" onClick={onClose}><X size={16} /></button>
        </div>
        <div className="modal-body">
          <DynamicForm
            endpoint="/api/formulario/novedades/"
            initialData={novedad}
            onSubmit={onSave}
          />
        </div>
        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>
            Cancelar
          </button>
          {isEdit && !novedad.generadoInforme && (
            <button
              className="btn btn-success"
              onClick={() => onGenerarInforme(novedad)}
            >
              <FileText size={14} /> Generar informe
            </button>
          )}
          <button
            type="submit"
            form="dynamic-form"
            className="btn btn-primary"
          >
            {isEdit ? "Guardar cambios" : "Registrar novedad"}
          </button>
        </div>
      </div>
    </div>
  );
}

function ModalDetalle({ novedad, onClose, onGenerarInforme, onNavigateInforme }) {
  const estadoStyle = getEstadoColor(novedad.estado_novedad);
  const prioColor = getPrioridadColor(novedad.nivel_prioridad);

  const secciones = [
    {
      title: "Fechas",
      fields: [
        { id: "fecha_novedad", icon: Clock, label: "Fecha de novedad", value: formatFechaHora(novedad.fecha_novedad) },
        { id: "fecha_solicitud", icon: Clock, label: "Fecha de solicitud", value: formatFechaHora(novedad.fecha_solicitud) },
      ],
    },
    {
      title: "Personas involucradas",
      fields: [
        { id: "analista", icon: User, label: "Analista de ingreso", value: novedad.analista },
        { id: "conductor", icon: User, label: "Conductor", value: novedad.conductor },
      ],
    },
    {
      title: "Vehículo y ruta",
      fields: [
        {
          id: "vehiculo",
          icon: Truck,
          label: "Vehículo",
          value: `${novedad.numero_interno} — ${novedad.vehiculo} — ${novedad.grupo_flota}`,
        },
        { id: "ruta", icon: MapPin, label: "Ruta", value: novedad.ruta },
        { id: "pasajeros", icon: AlertOctagon, label: "Pasajeros reportados", value: novedad.pasajeros_reportados },
      ],
    },
    {
      title: "Clasificación",
      fields: [
        { id: "cliente", icon: AlertTriangle, label: "Cliente", value: novedad.cliente },
        { id: "area_solicitante", icon: FileText, label: "Área solicitante", value: novedad.area_solicitante },
        {
          id: "categoria_tipo",
          icon: FileText,
          label: "Categoría informe",
          value: `${novedad.categoria_informe} / ${novedad.tipo_informe}`,
        },
        { id: "nas", icon: Hash, label: "NAS", value: novedad.nas },
      ],
    },
  ];

  return (
    <div className="modal-overlay">
      <div className="modal modal-lg">
        <div className="modal-header">
          <div className="modal-title"><Eye size={18} />Detalles de la novedad <b>{novedad.codigo_novedad}</b></div>
          <button className="btn-icon" onClick={onClose}><X size={16} /></button>
        </div>
        <div className="modal-body">
          {/* Header info */}
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 20 }}>
            <span className="badge" style={{ background: `${prioColor}20`, color: prioColor, border: `1px solid ${prioColor}40` }}>
              <AlertOctagon size={11} />{novedad.nivel_prioridad_display}
            </span>
            <span className="badge" style={{ background: estadoStyle.bg, color: estadoStyle.text }}>
              {novedad.estado_novedad_display}
            </span>
            <span className="tag">{novedad.tipo_informe}</span>
            {novedad.estado_dd_display && (
              <span className="badge" style={{ background: "rgba(59,130,246,0.15)", color: "var(--accent-primary)", border: "1px solid rgba(59,130,246,0.3)" }}>
                DD: {novedad.estado_dd_display}
              </span>
            )}
          </div>

          {secciones.map((s) => (
            <DetailSection key={s.title} title={s.title} fields={s.fields} />
          ))}

          {novedad.respuesta_novedad && (
            <div style={{ background: "var(--bg-surface)", borderRadius: "var(--radius-sm)", border: "1px solid var(--border)", padding: "14px 16px", marginBottom: 12 }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 8 }}>Respuesta de la novedad</div>
              <p style={{ fontSize: 13, color: "var(--text-secondary)", lineHeight: 1.7 }}>{novedad.respuesta_novedad}</p>
            </div>
          )}

          {novedad.observaciones && (
            <div style={{ background: "var(--bg-surface)", borderRadius: "var(--radius-sm)", border: "1px solid var(--border)", padding: "14px 16px" }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 8 }}>Observaciones</div>
              <p style={{ fontSize: 13, color: "var(--text-secondary)", lineHeight: 1.7 }}>{novedad.observaciones}</p>
            </div>
          )}
        </div>
        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>Cerrar</button>
          <button className="btn btn-primary" onClick={() => onGenerarInforme(novedad)}>
            <FileText size={14} /> Generar informe legal
          </button>
        </div>
      </div>
    </div>
  );
}

export default function NovedadesPage({ onGenerarInforme, onNavigateInforme }) {
  const [novedades, setNovedades] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(null);
  const [search, setSearch] = useState("");
  const [filtroEstado, setFiltroEstado] = useState("Todos");
  const [filtroPrioridad, setFiltroPrioridad] = useState("Todos");
  const [modal, setModal] = useState(null);
  const [selected, setSelected] = useState(null);
  const [toast, setToast] = useState(null);

  // Trae las novedades reales del backend al montar la página.
  // Antes el estado se inicializaba con mockData y nunca se refrescaba
  // contra el servidor, así que lo creado en sesiones previas no aparecía.
  useEffect(() => {
    let cancelado = false;

    async function cargarNovedades() {
      setLoading(true);
      setLoadError(null);
      try {
        const response = await fetch(`${API_BASE}/novedades/`, {
          credentials: "include",
        });
        if (!response.ok) {
          throw new Error(`El servidor respondió ${response.status}`);
        }
        const data = await response.json();
        if (!cancelado) setNovedades(data);
      } catch (err) {
        console.error("Error cargando novedades:", err);
        if (!cancelado) setLoadError(err.message);
      } finally {
        if (!cancelado) setLoading(false);
      }
    }

    cargarNovedades();
    return () => { cancelado = true; };
  }, []);

  // Filtro usando los nombres de campo reales que devuelve novedades_view
  // (codigo_novedad, tipo_informe, ruta, estado_novedad, nivel_prioridad),
  // no los del mock viejo (id, tipo, ubicacion, estado, prioridad).
  const filtered = novedades
    .filter((n) => {
      const term = search.toLowerCase();
      const matchSearch =
        !term ||
        n.codigo_novedad?.toLowerCase().includes(term) ||
        n.tipo_informe?.toLowerCase().includes(term) ||
        n.ruta?.toLowerCase().includes(term);
      const matchEstado = filtroEstado === "Todos" || n.estado_novedad === filtroEstado;
      const matchPrio = filtroPrioridad === "Todos" || n.nivel_prioridad === filtroPrioridad;
      return matchSearch && matchEstado && matchPrio;
    })
    .sort((a, b) => new Date(b.fecha_creacion) - new Date(a.fecha_creacion));

  const handleSave = async (form) => {
    try {
      const isEditing = modal === "editar" && selected;
      const url = isEditing
        ? `${API_BASE}/editar-novedad/${selected.id}/`
        : `${API_BASE}/crear-novedad/`;

      const response = await fetch(url, {
        // El backend (EditarNovedad) solo implementa post(), así que
        // usamos POST también al editar para no romper contra Django.
        // Si más adelante agregas def put() en la vista, cambia esto a "PUT".
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-CSRFToken": getCookie("csrftoken"),
        },
        credentials: "include",
        body: JSON.stringify(form),
      });

      const resultado = await response.json();

      if (!resultado.success) {
        throw new Error(resultado.mensaje || "Error al guardar la novedad");
      }

      if (isEditing) {
        setNovedades((ns) => ns.map((n) => (n.id === selected.id ? { ...n, ...form } : n)));
        setToast({ msg: "Novedad actualizada", type: "success" });
      } else {
        const nueva = { ...form, id: resultado.codigo, codigo_novedad: resultado.codigo, generadoInforme: false, informeId: null };
        setNovedades((ns) => [nueva, ...ns]);
        setToast({ msg: `Novedad ${resultado.codigo} registrada`, type: "success" });
      }

      setModal(null);
      setSelected(null);
    } catch (err) {
      console.error("Error guardando novedad:", err);
      setToast({ msg: `Error: ${err.message}`, type: "error" });
      // OJO: no cierres el modal si falla, para que el usuario no pierda sus datos
    }
  };

  const handleEliminar = async (id) => {
    try {
      const response = await fetch(`${API_BASE}/novedades/${id}/eliminar/`, {
        method: "DELETE",
        headers: {
          "X-CSRFToken": getCookie("csrftoken"),
        },
        credentials: "include",
      });

      const resultado = await response.json();

      if (!resultado.success) {
        throw new Error(resultado.mensaje || "Error al eliminar la novedad");
      }

      setNovedades((ns) => ns.filter((n) => n.id !== id));
      setToast({ msg: "Novedad eliminada", type: "success" });
    } catch (err) {
      console.error("Error eliminando novedad:", err);
      setToast({ msg: `Error: ${err.message}`, type: "error" });
    }
  };

  const handleGenerarInforme = (novedad) => {
    setModal(null);
    setSelected(null);
    onGenerarInforme(novedad);
  };

  const alertasCriticas = novedades.filter(
    (n) => n.nivel_prioridad === "Prioridad_Alta" && n.estado_novedad !== "Completado"
  ).length;

  return (
    <div className="page-shell">
      <div className="hero-panel compact">
        <div>
          <div className="hero-eyebrow">Flujo operatvo</div>
          <h2 className="hero-title">Gestiona novedades, evidencia y decisiones desde un único espacio</h2>
          <p className="hero-text">La vista prioriza los casos críticos, el estado de revisión y la posibilidad de avanzar directamente a la generación del informe.</p>
        </div>
        <div className="hero-actions">
          <button className="btn btn-primary" onClick={() => { setSelected(null); setModal("nuevo"); }}>
            <Plus size={15} /> Registrar novedad
          </button>
        </div>
      </div>

      <div className="hero-metrics">
        <div className="metric-pill"><strong>{novedades.length}</strong> registros</div>
        <div className="metric-pill"><strong>{alertasCriticas}</strong> alertas críticas</div>
        <div className="metric-pill"><strong>{filtered.filter((n) => n.estado_novedad === "Pendiente_por_responder").length}</strong> pendientes</div>
      </div>

      <div className="card">
        <div className="filters-bar">
          <div className="search-bar">
            <Search size={14} />
            <input
              placeholder="Buscar por código, tipo de informe o ruta..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            {ESTADOS_NOVEDAD.map((e) => (
              <button
                key={e.value}
                className={`btn btn-sm ${filtroEstado === e.value ? "btn-primary" : "btn-secondary"}`}
                onClick={() => setFiltroEstado(e.value)}
              >
                {e.label}
              </button>
            ))}
          </div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            {PRIORIDADES_NOVEDAD.map((p) => (
              <button
                key={p.value}
                className={`btn btn-sm ${filtroPrioridad === p.value ? "btn-primary" : "btn-secondary"}`}
                onClick={() => setFiltroPrioridad(p.value)}
              >
                {p.label}
              </button>
            ))}
          </div>
        </div>

        {loading && <div style={{ padding: 16, color: "var(--text-muted)" }}>Cargando novedades…</div>}
        {loadError && (
          <div style={{ padding: 16, color: "var(--accent-danger)" }}>
            No se pudieron cargar las novedades: {loadError}
          </div>
        )}

        {!loading && !loadError && (
          <NovedadesTable
            data={filtered}
            actions={[
              {
                key: "ver",
                label: "Ver detalle",
                tooltip: "Visualizar toda la información de la novedad",
                icon: "👁️",
                onClick: (row) => {
                  setSelected(row);
                  setModal("detalle");
                },
              },
              {
                key: "generar-informe",
                label: "Generar informe",
                tooltip: "Crear el informe asociado a esta novedad",
                icon: "📄",
                variant: "primary",
                onClick: (row) => onGenerarInforme(row),
                show: (row) => row.estado_novedad !== "Pendiente_por_responder",
              },
              {
                key: "editar",
                label: "Editar",
                tooltip: "Modificar la información de la novedad",
                icon: "✏️",
                variant: "secondary",
                onClick: (row) => {
                  setSelected(row);
                  setModal("editar");
                },
              },
              {
                key: "eliminar",
                label: "Eliminar",
                tooltip: "Eliminar permanentemente la novedad",
                icon: "🗑️",
                variant: "danger",
                onClick: (row) => {
                  if (
                    window.confirm(
                      `¿Eliminar la novedad ${row.codigo_novedad}? Esta acción no se puede deshacer.`
                    )
                  ) {
                    handleEliminar(row.id);
                  }
                },
              },
            ]}
          />
        )}
      </div>

      {(modal === "nuevo" || modal === "editar") && (
        <ModalNovedad novedad={modal === "editar" ? selected : null} onClose={() => setModal(null)} onSave={handleSave} onGenerarInforme={handleGenerarInforme} />
      )}
      {modal === "detalle" && selected && (
        <ModalDetalle novedad={selected} onClose={() => setModal(null)} onGenerarInforme={handleGenerarInforme} onNavigateInforme={onNavigateInforme} />
      )}
      {toast && <Toast message={toast.msg} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
}