const columnasLogioxDefault = [
  "FechaHora",
  "Placa",
  "Vehiculo",
  "Descripcion",
  "Viajo",
  "Oferta",
  "Conductor",
  "Cedula",
].map((label) => ({ id: nextId(), label }));

const columnasTrazabilidadDefault = ["Mes", "Fecha revisión", "Resultado", "Observación"].map((label) => ({ id: nextId(), label }));

const estadoInicialPositiva = () => ({
  logioxColumnas: columnasLogioxDefault,
  logioxFilas: [],
  solicitudTexto: "",
  recorridoNarrativa: "",
  recorridoMapaImagen: null,
  eventosCamara: [{ id: nextId(), horaInicio: "", horaFin: "", descripcion: "", imagen: null }],
});

const estadoInicialNegativa = () => ({
  trazabilidadColumnas: columnasTrazabilidadDefault,
  trazabilidadFilas: [],
  narrativa: "",
});

function CuerpoPositivaForm({ data, onChange }) {
  const [imageError, setImageError] = useState(null);
  const upd = useCallback((field, value) => onChange({ ...data, [field]: value }), [data, onChange]);

  const handleMapaChange = useCallback(
    (file) => {
      if (!file) return setImageError(null);
      readImageFile(
        file,
        (result) => {
          setImageError(null);
          upd("recorridoMapaImagen", result);
        },
        setImageError,
      );
    },
    [upd],
  );

  const addEvento = useCallback(() => {
    upd("eventosCamara", [
      ...data.eventosCamara,
      { id: nextId(), horaInicio: "", horaFin: "", descripcion: "", imagen: null },
    ]);
  }, [data.eventosCamara, upd]);

  const removeEvento = useCallback(
    (eventId) => {
      upd("eventosCamara", data.eventosCamara.filter((event) => event.id !== eventId));
    },
    [data.eventosCamara, upd],
  );

  const updateEvento = useCallback(
    (eventId, field, value) => {
      upd(
        "eventosCamara",
        data.eventosCamara.map((event) => (event.id === eventId ? { ...event, [field]: value } : event)),
      );
    },
    [data.eventosCamara, upd],
  );

  const handleEventoImagen = useCallback(
    (eventId, file) => {
      if (!file) return;
      readImageFile(
        file,
        (result) => {
          setImageError(null);
          updateEvento(eventId, "imagen", result);
        },
        setImageError,
      );
    },
    [updateEvento],
  );

  const moverEvento = useCallback(
    (index, direction) => {
      const target = index + direction;
      if (target < 0 || target >= data.eventosCamara.length) return;
      const copy = [...data.eventosCamara];
      [copy[index], copy[target]] = [copy[target], copy[index]];
      upd("eventosCamara", copy);
    },
    [data.eventosCamara, upd],
  );

  return (
    <div className="space-y-6">
      <div className="rounded-3xl border border-slate-700 bg-slate-950/80 p-6 shadow-xl shadow-slate-950/20">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h3 className="text-lg font-semibold text-white">Logiox</h3>
            <p className="mt-1 text-sm text-slate-400">Tabla dinámica para ruta, oferta y conductor.</p>
          </div>
          <button
            type="button"
            onClick={() =>
              upd("logioxFilas", [
                ...data.logioxFilas,
                {
                  id: nextId(),
                  cells: data.logioxColumnas.reduce((acc, column) => ({ ...acc, [column.id]: "" }), {}),
                },
              ])
            }
            className="inline-flex items-center gap-2 rounded-3xl bg-sky-500 px-4 py-3 text-sm font-semibold text-slate-950 transition hover:bg-sky-400"
          >
            <Plus size={16} /> Añadir fila
          </button>
        </div>
        <div className="mt-6">
          <EditableTable
            columns={data.logioxColumnas}
            rows={data.logioxFilas}
            onColumnsChange={(columns) => upd("logioxColumnas", columns)}
            onRowsChange={(rows) => upd("logioxFilas", rows)}
          />
        </div>
      </div>

      <div className="rounded-3xl border border-slate-700 bg-slate-950/80 p-6 shadow-xl shadow-slate-950/20">
        <h3 className="text-lg font-semibold text-white">Solicitud</h3>
        <p className="mt-1 text-sm text-slate-400">Describe con precisión la petición principal.</p>
        <textarea
          className="mt-5 min-h-[120px] w-full rounded-3xl border border-slate-700 bg-slate-900 px-4 py-4 text-sm text-slate-100 outline-none transition focus:border-sky-500 focus:ring-2 focus:ring-sky-500/30"
          rows={4}
          placeholder="Ej: Agradezco su apoyo revisando el DS del vehículo..."
          value={data.solicitudTexto}
          onChange={(event) => upd("solicitudTexto", event.target.value)}
          aria-label="Solicitud de soporte"
        />
      </div>

      <div className="rounded-3xl border border-slate-700 bg-slate-950/80 p-6 shadow-xl shadow-slate-950/20">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h3 className="text-lg font-semibold text-white">Recorrido</h3>
            <p className="mt-1 text-sm text-slate-400">Agrega el detalle del trayecto y un soporte visual opcional.</p>
          </div>
          <span className="rounded-full bg-slate-900 px-3 py-1 text-xs uppercase tracking-[0.24em] text-slate-400">Opcional</span>
        </div>
        <textarea
          className="mt-5 min-h-[140px] w-full rounded-3xl border border-slate-700 bg-slate-900 px-4 py-4 text-sm text-slate-100 outline-none transition focus:border-sky-500 focus:ring-2 focus:ring-sky-500/30"
          rows={5}
          placeholder="Descripción de los hechos según lo confrontado en plataforma y disco duro..."
          value={data.recorridoNarrativa}
          onChange={(event) => upd("recorridoNarrativa", event.target.value)}
          aria-label="Narrativa del recorrido"
        />
        <label className="mt-5 flex cursor-pointer items-center justify-between rounded-3xl border border-dashed border-slate-700 bg-slate-900 px-4 py-4 text-sm text-slate-300 transition hover:border-sky-500 hover:text-slate-100">
          <span className="flex items-center gap-2">
            <ImageIcon size={16} /> Agregar mapa de recorrido
          </span>
          <input type="file" accept="image/*" className="hidden" onChange={(event) => handleMapaChange(event.target.files?.[0])} aria-label="Subir mapa de recorrido" />
        </label>
        {imageError && <div className="mt-3 text-sm text-rose-400">{imageError}</div>}
        {data.recorridoMapaImagen && (
          <img src={data.recorridoMapaImagen} alt="Mapa de recorrido" className="mt-5 w-full rounded-3xl border border-slate-700 object-cover" />
        )}
      </div>

      <div className="rounded-3xl border border-slate-700 bg-slate-950/80 p-6 shadow-xl shadow-slate-950/20">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h3 className="text-lg font-semibold text-white">Evidencia de cámaras</h3>
            <p className="mt-1 text-sm text-slate-400">Registra cada evento con tiempos, descripción y soporte visual.</p>
          </div>
          <button
            type="button"
            onClick={addEvento}
            className="inline-flex items-center gap-2 rounded-3xl bg-slate-800 px-4 py-3 text-sm font-semibold text-slate-200 transition hover:bg-slate-700"
          >
            <Plus size={16} /> Añadir evento
          </button>
        </div>
        <div className="mt-6 space-y-4">
          {data.eventosCamara.map((event, index) => (
            <div key={event.id} className="rounded-3xl border border-slate-700 bg-slate-900/95 p-5 shadow-inner shadow-slate-950/20">
              <div className="flex items-center justify-between gap-3">
                <div className="text-sm font-semibold text-slate-100">Evento {index + 1}</div>
                <div className="flex items-center gap-2">
                  <TableButton onClick={() => moverEvento(index, -1)} title="Mover arriba" icon={<ChevronUp size={14} />} disabled={index === 0} />
                  <TableButton
                    onClick={() => moverEvento(index, 1)}
                    title="Mover abajo"
                    icon={<ChevronDown size={14} />}
                    disabled={index === data.eventosCamara.length - 1}
                  />
                  <TableButton onClick={() => removeEvento(event.id)} title="Eliminar evento" icon={<Trash2 size={14} />} />
                </div>
              </div>
              <div className="mt-4 grid gap-4 sm:grid-cols-2">
                <label className="text-sm text-slate-300">
                  Inicio
                  <input
                    type="time"
                    value={event.horaInicio}
                    onChange={(eventData) => updateEvento(event.id, "horaInicio", eventData.target.value)}
                    className="mt-2 w-full rounded-3xl border border-slate-700 bg-slate-900 px-3 py-3 text-sm text-slate-100 outline-none transition focus:border-sky-500 focus:ring-2 focus:ring-sky-500/30"
                  />
                </label>
                <label className="text-sm text-slate-300">
                  Fin
                  <input
                    type="time"
                    value={event.horaFin}
                    onChange={(eventData) => updateEvento(event.id, "horaFin", eventData.target.value)}
                    className="mt-2 w-full rounded-3xl border border-slate-700 bg-slate-900 px-3 py-3 text-sm text-slate-100 outline-none transition focus:border-sky-500 focus:ring-2 focus:ring-sky-500/30"
                  />
                </label>
              </div>
              <label className="block text-sm text-slate-300">
                Descripción
                <input
                  value={event.descripcion}
                  onChange={(eventData) => updateEvento(event.id, "descripcion", eventData.target.value)}
                  placeholder="Ej: Sube el menor al vehículo"
                  className="mt-2 w-full rounded-3xl border border-slate-700 bg-slate-900 px-3 py-3 text-sm text-slate-100 outline-none transition focus:border-sky-500 focus:ring-2 focus:ring-sky-500/30"
                />
              </label>
              <label className="mt-4 flex cursor-pointer items-center justify-between rounded-3xl border border-dashed border-slate-700 bg-slate-900 px-4 py-4 text-sm text-slate-300 transition hover:border-sky-500 hover:text-slate-100">
                <span>Cargar imagen del evento</span>
                <input
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={(eventData) => handleEventoImagen(event.id, eventData.target.files?.[0])}
                />
              </label>
              {event.imagen && (
                <img src={event.imagen} alt={`Captura evento ${index + 1}`} className="mt-4 w-full rounded-3xl border border-slate-700 object-cover" />
              )}
            </div>
          ))}
        </div>
        {imageError && <div className="mt-3 text-sm text-rose-400">{imageError}</div>}
      </div>
    </div>
  );
}

