import React, { useState, useMemo } from "react";
import {
  FileText, Plus, Eye, Download, Printer, X, CheckCircle2,
  AlertTriangle, Building2, Truck, MapPin, User, Clock, Scale,
  Search, Filter, SortAsc, RefreshCw, Paperclip
} from "lucide-react";
import { informes as initialInformes, novedades, clientes, vehiculos } from "../data/mockData";
import { formatFechaHora, formatFecha, generarIdInforme } from "../utils/helpers";
import Toast from "../components/ui/Toast";
import InformeBuilderTemplate from "../components/plantillas/plantillaInforme";
import InformeBuilder from "./InformeBuilder/InformeBuilderPage";

// ... InformePreview y ModalGenerarInforme se quedan igual ...

export default function InformesPage({ novedadParaInforme, onClearNovedad, highlightId }) {
  const [informes, setInformes] = useState(initialInformes);
  const [modal, setModal] = useState(novedadParaInforme ? "generar" : null);
  const [selectedInforme, setSelectedInforme] = useState(null);
  const [novedadActiva, setNovedadActiva] = useState(novedadParaInforme);
  const [toast, setToast] = useState(null);
  const [search, setSearch] = useState("");
  const [filtroEstado, setFiltroEstado] = useState("Todos");
  const [filtroCliente, setFiltroCliente] = useState("Todos");
  const [ordenFecha, setOrdenFecha] = useState("desc");

  const novedadDemo = {
    codigo_novedad: "NAS-SC-1262",
    cliente: "Flota La Macarena",
    conductor: "Fabian Leonardo Rueda Acosta",
    numero_interno: "7389",
    vehiculo: "TSW878",
  };

  React.useEffect(() => {
    if (novedadParaInforme) { 
      setNovedadActiva(novedadParaInforme); 
      setModal("generar"); 
    }
  }, [novedadParaInforme]);

  const handleCrear = (form) => {
    const nuevo = {
      ...form,
      id: generarIdInforme(informes),
      novedadId: novedadActiva.id,
      fecha: new Date().toISOString(),
      estado: "Finalizado",
      adjuntos: [],
    };
    setInformes(is => [nuevo, ...is]);
    setToast({ msg: `Informe ${nuevo.id} generado exitosamente`, type: "success" });
    setModal(null);
    setNovedadActiva(null);
    if (onClearNovedad) onClearNovedad();
    setTimeout(() => { setSelectedInforme(nuevo); setModal("ver"); }, 300);
  };

  const resetFilters = () => {
    setSearch("");
    setFiltroEstado("Todos");
    setFiltroCliente("Todos");
    setOrdenFecha("desc");
  };

  const estadosDisponibles = ["Todos", ...Array.from(new Set(informes.map(i => i.estado)))];
  const clientesDisponibles = ["Todos", ...Array.from(new Set(informes.map(i => clientes.find(c => c.id === (novedades.find(n => n.id === i.novedadId)?.cliente))?.razonSocial).filter(Boolean)))];

  const informesFiltrados = useMemo(() => {
    const q = search.trim().toLowerCase();
    return [...informes]
      .filter(inf => {
        const novedad = novedades.find(n => n.id === inf.novedadId);
        const cliente = clientes.find(c => c.id === novedad?.cliente);
        const texto = [inf.id, inf.tipo, inf.novedadId, inf.codigo_novedad, cliente?.razonSocial, inf.elaboradoPor, inf.placa, inf.numero_interno]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();
        const matchSearch = q === "" || texto.includes(q);
        const matchEstado = filtroEstado === "Todos" || inf.estado === filtroEstado;
        const matchCliente = filtroCliente === "Todos" || cliente?.razonSocial === filtroCliente;
        return matchSearch && matchEstado && matchCliente;
      })
      .sort((a, b) => {
        if (ordenFecha === "asc") return new Date(a.fecha) - new Date(b.fecha);
        return new Date(b.fecha) - new Date(a.fecha);
      });
  }, [informes, search, filtroEstado, filtroCliente, ordenFecha]);

  if (modal === "plantilla") {
    return (
      <InformeBuilder
        data={novedadDemo}
        onVolver={() => setModal(null)}
        onGuardar={(payload) => {
          console.log("Payload de prueba (provisional):", payload);
          setModal(null);
        }}
      />
    );
  }

  return (
    <div className="page-shell">
      <div className="hero-panel compact">
        <div>
          <div className="hero-eyebrow">Informes legales</div>
          <h2 className="hero-title">Convierte cada caso revisado en un informe claro y accionable</h2>
          <p className="hero-text">La vista organiza los informes por contexto, cliente y estado para mejorar la trazabilidad del proceso.</p>
        </div>
        <div className="hero-actions">
          <button 
            className="btn btn-primary"
            onClick={() => setModal("plantilla")}
          >
            <FileText size={16} />
            Ver plantilla de prueba
          </button>
        </div>
      </div>

      <div className="hero-metrics">
        <div className="metric-pill"><strong>{informes.length}</strong> informes</div>
        <div className="metric-pill"><strong>{informes.filter((i) => i.estado === "Finalizado").length}</strong> finalizados</div>
        <div className="metric-pill"><strong>{informes.filter((i) => i.estado !== "Finalizado").length}</strong> en proceso</div>
      </div>

      {/* Barra de Herramientas y Filtros */}
      <div className="bg-white rounded-2xl border border-slate-200/80 p-5 shadow-sm space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-12 gap-3">
          <div className="md:col-span-6 relative">
            <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="search"
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:bg-white transition-all"
              placeholder="Buscar por ID, tipo, cliente, placa..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              aria-label="Buscar informes"
            />
          </div>
          <div className="md:col-span-3">
            <select 
              className="w-full px-3 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:bg-white transition-all" 
              value={filtroEstado} 
              onChange={e => setFiltroEstado(e.target.value)} 
              aria-label="Filtrar por estado"
            >
              {estadosDisponibles.map(estado => <option key={estado} value={estado}>{estado === 'Todos' ? 'Todos los estados' : estado}</option>)}
            </select>
          </div>
          <div className="md:col-span-3">
            <select 
              className="w-full px-3 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 focus:bg-white transition-all" 
              value={filtroCliente} 
              onChange={e => setFiltroCliente(e.target.value)} 
              aria-label="Filtrar por cliente"
            >
              {clientesDisponibles.map(cliente => <option key={cliente} value={cliente}>{cliente === 'Todos' ? 'Todos los clientes' : cliente}</option>)}
            </select>
          </div>
        </div>

        {/* Resumen de búsqueda y ordenamiento */}
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 pt-2 border-t border-slate-100">
          <div className="flex flex-wrap items-center gap-2 text-xs font-medium text-slate-500">
            <span className="bg-slate-100 text-slate-700 px-2.5 py-1 rounded-md font-semibold">
              {informesFiltrados.length} resultados
            </span>
            {search && <span className="bg-blue-50 text-blue-600 px-2 py-1 rounded-md">Buscando: "{search}"</span>}
            {filtroEstado !== "Todos" && <span className="bg-amber-50 text-amber-700 px-2 py-1 rounded-md">Estado: {filtroEstado}</span>}
            {filtroCliente !== "Todos" && <span className="bg-purple-50 text-purple-700 px-2 py-1 rounded-md">Cliente: {filtroCliente}</span>}
          </div>
          
          <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
            <button 
              className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-slate-50 hover:bg-slate-100 border border-slate-200 rounded-lg text-xs font-semibold text-slate-600 transition-all"
              onClick={() => setOrdenFecha(prev => prev === "desc" ? "asc" : "desc")}
            >
              <SortAsc size={13} />
              Fecha {ordenFecha === "desc" ? "Recientes primero" : "Antiguos primero"}
            </button>
            <button 
              className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-white hover:bg-slate-50 border border-slate-200 rounded-lg text-xs font-semibold text-rose-600 transition-all" 
              onClick={resetFilters}
            >
              <RefreshCw size={13} />
              Limpiar filtros
            </button>
          </div>
        </div>
      </div>

      {/* Lista / Grid de Informes */}
      {informesFiltrados.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center max-w-xl mx-auto shadow-sm">
          <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-slate-100">
            <FileText size={28} className="text-slate-400" />
          </div>
          <h3 className="text-base font-bold text-slate-800">No se encontraron informes</h3>
          <p className="text-sm text-slate-500 mt-1 max-w-sm mx-auto">
            Prueba ajustando los filtros o buscando un término diferente. Los informes válidos se generan desde las novedades.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {informesFiltrados.map(inf => {
            const novedad = novedades.find(n => n.id === inf.novedadId);
            const cliente = clientes.find(c => c.id === novedad?.cliente);
            const isHighlight = inf.id === highlightId;
            
            return (
              <div
                key={inf.id}
                className={`group bg-white rounded-2xl border transition-all duration-200 flex flex-col justify-between overflow-hidden shadow-sm hover:shadow-md hover:border-slate-300 ${
                  isHighlight ? "ring-2 ring-blue-500 border-transparent shadow-blue-100" : "border-slate-200/90"
                }`}
              >
                {/* Cuerpo Superior de la Tarjeta */}
                <div className="p-5 space-y-4">
                  {/* Fila de ID y Estado */}
                  <div className="flex justify-between items-start gap-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-blue-50 border border-blue-100 rounded-xl flex items-center justify-center shrink-0">
                        <Scale size={18} className="text-blue-600" />
                      </div>
                      <div>
                        <span className="font-mono font-bold text-sm text-blue-600 tracking-wider block">{inf.id}</span>
                        <span className="text-xs font-semibold text-slate-400 block mt-0.5">
                          {novedad?.codigo_novedad || inf.codigo_novedad || inf.novedadId}
                        </span>
                      </div>
                    </div>
                    
                    <div className="flex flex-col items-end gap-1.5">
                      <span className="inline-flex items-center gap-1 px-2 py-1 rounded-md text-xs font-bold bg-green-50 text-green-700 border border-green-200/60">
                        <CheckCircle2 size={12} className="text-green-600" />
                        {inf.estado}
                      </span>
                      {isHighlight && (
                        <span className="bg-blue-600 text-white text-[10px] font-extrabold uppercase px-1.5 py-0.5 rounded tracking-wide animate-pulse">
                          Nuevo
                        </span>
                      )}
                    </div>
                  </div>

                  {/* Tipo de informe */}
                  <h2 className="font-bold text-slate-800 text-base leading-tight group-hover:text-blue-600 transition-colors">
                    {inf.tipo}
                  </h2>

                  {/* Información Detallada */}
                  <div className="space-y-2.5 text-xs text-slate-600 pt-1">
                    <div className="flex items-center gap-2.5">
                      <Building2 size={14} className="text-slate-400 shrink-0" />
                      <span className="font-medium text-slate-700 truncate">{cliente?.razonSocial || "Cliente no asignado"}</span>
                    </div>
                    <div className="flex items-center gap-2.5">
                      <User size={14} className="text-slate-400 shrink-0" />
                      <span className="truncate">{inf.elaboradoPor || novedad?.conductor || "Sin responsable asignado"}</span>
                    </div>
                    <div className="flex items-center gap-2.5">
                      <Clock size={14} className="text-slate-400 shrink-0" />
                      <span>{formatFechaHora(inf.fecha)}</span>
                    </div>
                  </div>
                </div>

                {/* Zona Inferior Meta y Acciones */}
                <div className="px-5 pb-5 pt-3 bg-slate-50/70 border-t border-slate-100 mt-auto space-y-3">
                  {/* Badges de Vehículo / Adjuntos */}
                  <div className="flex flex-wrap gap-1.5">
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-sky-50/80 border border-sky-100 rounded-lg text-xs font-medium text-sky-700">
                      <Truck size={12} />
                      <span className="font-semibold">{inf.placa || novedad?.vehiculo || "—"}</span>
                    </span>
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-rose-50/80 border border-rose-100 rounded-lg text-xs font-medium text-rose-700">
                      <MapPin size={12} />
                      <span>Int. {inf.numero_interno || novedad?.numero_interno || "N/A"}</span>
                    </span>
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-slate-200/60 rounded-lg text-xs font-medium text-slate-600 ml-auto">
                      <Paperclip size={11} />
                      {inf.adjuntos?.length ?? 0}
                    </span>
                  </div>

                  {/* Botones de Acción */}
                  <div className="grid grid-cols-2 gap-2 pt-1">
                    <button 
                      className="inline-flex items-center justify-center gap-1.5 px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold text-slate-700 hover:bg-slate-50 hover:border-slate-300 transition-all shadow-sm active:scale-95"
                      onClick={() => { setSelectedInforme(inf); setModal("ver"); }}
                    >
                      <Eye size={14} className="text-slate-500" />
                      Ver detalle
                    </button>
                    <button 
                      className="inline-flex items-center justify-center gap-1.5 px-3 py-2 bg-slate-800 hover:bg-slate-900 rounded-xl text-xs font-bold text-white transition-all shadow-sm active:scale-95"
                      onClick={() => window.print()}
                    >
                      <Printer size={14} />
                      Imprimir
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Modales y Notificaciones */}
      {modal === "generar" && novedadActiva && (
        <ModalGenerarInforme 
          novedad={novedadActiva} 
          onClose={() => { setModal(null); setNovedadActiva(null); if (onClearNovedad) onClearNovedad(); }} 
          onCrear={handleCrear} 
        />
      )}
      {modal === "ver" && selectedInforme && (
        <InformePreview informe={selectedInforme} onClose={() => setModal(null)} />
      )}
      {toast && <Toast message={toast.msg} type={toast.type} onClose={() => setToast(null)} />}
    </div>
  );
}