import React, { useMemo } from "react";
import InformeBuilderTemplate from "../../components/plantillas/plantillaInforme";

const novedadFallback = {
  codigo_novedad: "NAS-SC-1262",
  cliente: "Flota La Macarena",
  conductor: "Fabian Leonardo Rueda Acosta",
  numero_interno: "7389",
  vehiculo: "TSW878",
};

export default function InformeBuilderPage({ data, onVolver, onGuardar }) {
  const novedad = useMemo(() => data ?? novedadFallback, [data]);

  return (
    <div className="min-h-screen bg-slate-950/10 py-8">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <div className="mb-6 rounded-[2rem] border border-slate-800 bg-slate-950/95 p-6 shadow-2xl shadow-slate-950/20">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="text-sm uppercase tracking-[0.24em] text-sky-400">Generador de informes</p>
              <h1 className="mt-2 text-3xl font-semibold text-white">Editor de informe profesional</h1>
              <p className="mt-2 max-w-2xl text-sm text-slate-400">Usa una experiencia más limpia y efectiva para construir informes precisos y listos para impresión.</p>
            </div>
            {onVolver && (
              <button
                type="button"
                onClick={onVolver}
                className="inline-flex items-center justify-center rounded-full border border-slate-700 bg-slate-900 px-5 py-3 text-sm font-semibold text-slate-100 transition hover:border-sky-500 hover:bg-slate-800"
              >
                Volver
              </button>
            )}
          </div>
        </div>

        <InformeBuilderTemplate
          novedad={novedad}
          onVolver={onVolver}
          onGuardar={onGuardar}
        />
      </div>
    </div>
  );
}
