import React, { useState, useEffect } from "react";
import "./index.css";
import Sidebar from "./components/layout/Sidebar";
import Topbar from "./components/layout/Topbar";
import DashboardPage from "./pages/DashboardPage";
import ClientesPage from "./pages/ClientesPage";
import MantenimientoPage from "./pages/MantenimientosPage" ;
import NovedadesPage from "./pages/NovedadesPage";
import InformesPage from "./pages/InformesPage";
import InformeBuilderPage from "./pages/InformeBuilder/InformeBuilderPage";
import MonitoreoPage from "./pages/MonitoreoPage";
import { novedades } from "./data/mockData";

export default function App() {
  const [page, setPage] = useState("dashboard");
  const [novedadParaInforme, setNovedadParaInforme] = useState(null);
  const [informeBuilderData, setInformeBuilderData] = useState(null);
  const [highlightInformeId, setHighlightInformeId] = useState(null);
  const [novedadPreseleccionada, setNovedadPreseleccionada] = useState(null);

  // Al montar la app, pedimos que Django setee la cookie 'csrftoken'
  // en el navegador. Sin esto, los POST/PUT/DELETE fallarán con 403.
  useEffect(() => {
    fetch("http://localhost:8000/api/csrf/", { credentials: "include" })
      .catch(err => console.error("No se pudo obtener el CSRF token:", err));
  }, []);

  const alertCount = novedades.filter(
    n => n.prioridad === "Alta" && n.estado !== "Cerrada"
  ).length;

  const handleGenerarInforme = (novedad) => {
    setNovedadParaInforme(novedad);
    setInformeBuilderData(novedad);
    setPage("builderInforme");
  };

  const handleGuardarInforme = (payload) => {
    console.log("Informe guardado:", payload);
    setInformeBuilderData(null);
    setNovedadParaInforme(null);
    setPage("informes");
  };

  const handleNavigateInforme = (informeId) => {
    setHighlightInformeId(informeId);
    setPage("informes");
  };

  const handleNovedadDesdeMonitoreo = (vehiculo) => {
    setNovedadPreseleccionada(vehiculo);
    setPage("novedades");
  };

  return (
    <div className="app-shell">
      <Sidebar active={page} onNavigate={setPage} alertCount={alertCount} />
      <div className="main-area">
        <Topbar page={page} alertCount={alertCount} />
        <div className="page-content">
          {page === "dashboard" && <DashboardPage onNavigate={setPage} />}
          {page === "monitoreo" && <MonitoreoPage onNovedad={handleNovedadDesdeMonitoreo} />}
          {page === "clientes" && <ClientesPage />}
          {page === "mantenimientos" && <MantenimientoPage/>}
          {page === "novedades" && (
            <NovedadesPage
              onGenerarInforme={handleGenerarInforme}
              onNavigateInforme={handleNavigateInforme}
              vehiculoPreseleccionado={novedadPreseleccionada}
            />
          )}
          {page === "informes" && (
            <InformesPage
              novedadParaInforme={novedadParaInforme}
              onClearNovedad={() => setNovedadParaInforme(null)}
              highlightId={highlightInformeId}
            />
          )}
          {page === "builderInforme" && (
            <InformeBuilderPage
              data={informeBuilderData}
              onVolver={() => {
                setInformeBuilderData(null);
                setNovedadParaInforme(null);
                setPage("informes");
              }}
              onGuardar={handleGuardarInforme}
            />
          )}
        </div>
      </div>
    </div>
  );
}